# Étape 1 : données pour le cahier, le livret du maître et le site (le livre de l'élève est rédigé dans c_e1.py)
from ctx import *
E = 1
ISTI = 'أَعُوذُ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ'

L1 = lesson(e=E, n=1, title='Le tajwîd : donner à chaque lettre son droit', ar='تَجْوِيدٌ',
    obj=['savoir ce que signifie le mot **tajwîd** ;', 'distinguer le **droit** d’une lettre et son **dû** ;', 'connaître la place du tajwîd dans la récitation du Coran.'],
    dec=[('t', 'Le mot **tajwîd** (تَجْوِيدٌ) vient du verbe جَوَّدَ, « rendre beau, bien faire ». Pour la récitation du Coran, c’est **prononcer chaque lettre comme il faut** : de son bon point de sortie, avec ses qualités, et en appliquant les règles qui changent selon sa place.'),
         ('g', ['', 'Ce que c’est', 'Exemple'], [['**Le droit** (ḥaqq)', 'ce qui ne quitte jamais la lettre : point de sortie, qualités permanentes', ('AR', W(1, 6, 2))], ['**Le dû** (mustaḥaqq)', 'ce qui dépend de sa place : ghounna, allongement, épaisseur du râ’…', ('AR', W(1, 7, 9))]], [2600, 5146, 2400]),
         ('v', V(73, 4), '« … et récite le Coran lentement et clairement. » (Al-Mouzzammil, 4)'),
         ('q', '« Appliquer le tajwîd est une obligation ferme : celui qui ne récite pas le Coran correctement est en faute. Car c’est ainsi qu’Allah l’a fait descendre, et c’est ainsi qu’il nous est parvenu de Lui. »', 'Ibn al-Jazarî, Al-Mouqaddima', 'وَٱلْأَخْذُ بِٱلتَّجْوِيدِ حَتْمٌ لَازِمُ')],
    ecoute=['Écoutez ٱلْحَمْدُ : le ḥâ’ est soufflé du milieu de la gorge, le mîm s’arrête net. Écoutez ٱلضَّآلِّينَ : la voix tient l’alif environ six temps.'],
    ret=['Le **tajwîd**, c’est réciter chaque lettre comme il faut.', 'Le **droit** de la lettre ne change jamais ; son **dû** dépend de sa place.', 'Le Coran se récite comme il a été révélé et transmis : avec le tajwîd.'],
    lis=[V(1, 1), V(1, 2), V(1, 3) + '  ' + V(1, 4), V(1, 5), V(1, 6), V(1, 7)],
    lis_corr=['Lisez la Fâtiḥa lentement, en surveillant chaque lettre : ḥâ’ soufflé, ‘ayn de la gorge, chadda de إِيَّاكَ, ṣâd et ḍâd épais.'],
    mots=[M(1, 6, 2, note='ṣâd épais'), M(1, 2, 1, note='ḥâ’ soufflé'), M(1, 2, 4, note='‘ayn'), M(112, 1, 1, note='qâf'), M(112, 2, 2, note='ṣâd'), M(1, 7, 6, note='ḍâd')],
    cahier=[dict(title='Je complète', kind='bul', data=['Le mot tajwîd vient du verbe جَوَّدَ, qui veut dire « ……………… ».', 'Le point de sortie et les qualités permanentes forment le ……… de la lettre.', 'Ce qui dépend de la place de la lettre forme son ……… .'],
                 corr=['rendre beau, bien faire • droit • dû.']),
            dict(title='Je relie', kind='relier', data=(['le droit de la lettre', 'le dû de la lettre', 'Ibn al-Jazarî', 'Al-Mouzzammil, 4'], ['« et récite le Coran lentement et clairement »', 'ghounna, allongement, râ’ épais ou fin', 'point de sortie et qualités permanentes', 'auteur d’un célèbre poème sur le tajwîd']),
                 corr=['1 → C • 2 → B • 3 → D • 4 → A.']),
            dict(title='Je recopie', instr='Recopiez le verset 4 de la sourate Al-Mouzzammil à partir de وَرَتِّلِ, avec toutes ses voyelles.', kind='write', data=1, corr=['وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا.'])],
    mini=[('Le mot **tajwîd** veut dire…', ['rendre beau, bien faire', 'réciter vite', 'apprendre par cœur']),
          ('Le **droit** de la lettre, c’est…', ['son point de sortie et ses qualités permanentes', 'ce qui dépend de sa place', 'sa voyelle']),
          ('Le **dû** de la lettre, c’est…', ['ce qui dépend de sa place (ghounna, allongement…)', 'son point de sortie', 'son nom']),
          ('Le verset « wa rattili l-Qour’âna tartîlâ » est dans la sourate…', ['Al-Mouzzammil', 'Al-Fâtiḥa', 'Al-Ikhlâṣ'])],
    cards=[('tajwîd', 'donner à chaque lettre son droit et son dû'), ('ḥaqq', 'le droit de la lettre : point de sortie, qualités permanentes'), ('mustaḥaqq', 'le dû de la lettre : ce qui dépend de sa place')])

L2 = lesson(e=E, n=2, title='Les rythmes de la récitation : taḥqîq, tadwîr, ḥadr', ar='تَرْتِيلًا',
    obj=['connaître le **tartîl**, la récitation posée demandée par le Coran ;', 'distinguer les trois rythmes : **taḥqîq**, **tadwîr** et **ḥadr** ;', 'garder les mêmes règles quel que soit le rythme.'],
    dec=[('t', 'Allah demande de réciter le Coran avec **tartîl** : posément, en donnant à chaque lettre son temps. ‘Alî l’a expliqué ainsi : « Le tartîl, c’est bien prononcer les lettres et connaître les arrêts. »'),
         ('g', ['Rythme', 'Comment ?', 'Pour qui, quand ?'], [['**At-taḥqîq** — le plus lent', 'très posé', 'pour apprendre et enseigner'], ['**At-tadwîr** — moyen', 'ni lent ni rapide', 'récitation de tous les jours'], ['**Al-ḥadr** — rapide', 'rapide, règles gardées', 'révision de la mémorisation']], [2900, 3646, 3600])],
    ecoute=['Récitez ' + V(112, 1) + ' trois fois : taḥqîq, tadwîr, ḥadr. À chaque vitesse, le qâf reste net et le dâl se fait entendre à l’arrêt.'],
    ret=['Le **tartîl** : bien prononcer les lettres et connaître les arrêts.', 'Trois rythmes : **taḥqîq**, **tadwîr**, **ḥadr**.', 'Le rythme change la vitesse, **jamais** les règles.'],
    lis=[V(103, 1), V(103, 2), V(103, 3), V(108, 1), V(108, 2), V(108, 3)],
    lis_corr=['Lisez chaque verset trois fois : lentement, à vitesse moyenne, puis plus vite, sans perdre une lettre ni raccourcir un allongement.'],
    mots=[M(73, 4, 4, 6), M(17, 106, 1, 7), M(25, 32, 14, 15), M(75, 16, 1, 6), M(75, 18, 1, 4), M(96, 1, 1, 3)],
    cahier=[dict(title='Je relie', kind='relier', data=(['taḥqîq', 'tadwîr', 'ḥadr'], ['rapide, règles gardées', 'le plus lent, pour apprendre', 'moyen']), corr=['taḥqîq → B • tadwîr → C • ḥadr → A.']),
            dict(title='Vrai ou faux ?', kind='vf', data=['En ḥadr, on peut raccourcir un allongement obligatoire.', 'Le taḥqîq sert à apprendre et à enseigner.', 'Le tartîl est demandé par le Coran.'], corr=['1. Faux. • 2. Vrai. • 3. Vrai (Al-Mouzzammil, 4).'])],
    mini=[('Le rythme le plus lent s’appelle…', ['at-taḥqîq', 'al-ḥadr', 'at-tadwîr']), ('Le rythme moyen s’appelle…', ['at-tadwîr', 'at-taḥqîq', 'al-ḥadr']),
          ('Quand on récite vite (ḥadr)…', ['on garde toutes les règles', 'on peut sauter des lettres', 'on raccourcit les madd'])],
    cards=[('tartîl', 'récitation posée : bien prononcer les lettres, connaître les arrêts'), ('taḥqîq • tadwîr • ḥadr', 'lent • moyen • rapide')])

L3 = lesson(e=E, n=3, title='L’isti‘âdha et la basmala', ar='بِسْمِ ٱللَّهِ',
    obj=['dire l’**isti‘âdha** avant de réciter ;', 'savoir où dire la **basmala** et où ne pas la dire ;', 'enchaîner isti‘âdha, basmala et début de sourate de la bonne façon.'],
    dec=[('v', V(16, 98), '« Lorsque tu lis le Coran, demande la protection d’Allah contre Satan le lapidé. » (An-Naḥl, 98)'),
         ('t', 'On dit l’isti‘âdha au début de la récitation : ' + ISTI + '. La basmala se dit au début de chaque sourate, **sauf At-Tawba** ; au milieu d’une sourate, elle est au choix.'),
         ('g', ['Entre deux sourates', 'Statut'], [['tout séparer', 'permis'], ['tout enchaîner', 'permis'], ['séparer la fin de sourate, enchaîner basmala et sourate suivante', 'permis'], ['enchaîner la fin de sourate et la basmala, puis s’arrêter', '**interdit**']], [7146, 3000])],
    ecoute=['Dans ' + ISTI + ', faites entendre le ‘ayn de أَعُوذُ et le ṭâ’ épais de ٱلشَّيْطَٰنِ.'],
    ret=['L’**isti‘âdha** se dit avant de réciter.', 'La **basmala** se dit au début de chaque sourate, sauf At-Tawba.', 'Entre deux sourates, ne jamais coller la basmala à la fin de la sourate puis s’arrêter.'],
    lis=[ISTI, V(1, 1), V(112, 1) + '  ' + V(112, 2), V(113, 5), V(114, 1), V(9, 1)],
    lis_corr=['Ligne 1 : ‘ayn, ṭâ’ épais. Ligne 2 : lâm d’Allah fin après la kasra. Lignes 4-5 : essayez les trois façons permises entre Al-Falaq et An-Nâs. Ligne 6 : At-Tawba, sans basmala.'],
    mots=[M(16, 98, 4, 8), M(9, 1, 1, 3), M(27, 30, 5, 8)],
    cahier=[dict(title='Je complète', kind='bul', data=['Avant de réciter, je dis l’……… .', 'La basmala ne se dit pas au début de la sourate ……… .', 'Au milieu d’une sourate, la basmala est ……… .'], corr=['isti‘âdha • At-Tawba • au choix.']),
            dict(title='Permis ou interdit ?', kind='vf', data=['Tout enchaîner : fin de sourate, basmala, sourate suivante.', 'Coller la basmala à la fin de la sourate puis s’arrêter.', 'Tout séparer.'], corr=['1. Vrai (permis). • 2. Faux (interdit). • 3. Vrai (permis).'])],
    mini=[('On ne dit pas la basmala au début de la sourate…', ['At-Tawba', 'Al-Fâtiḥa', 'An-Nâs']), ('Au milieu d’une sourate, la basmala est…', ['au choix', 'obligatoire', 'interdite']),
          ('Quelle façon est **interdite** entre deux sourates ?', ['coller la basmala à la fin de la sourate puis s’arrêter', 'tout séparer', 'tout enchaîner'])],
    cards=[('isti‘âdha', 'أَعُوذُ بِٱللَّهِ مِنَ ٱلشَّيْطَٰنِ ٱلرَّجِيمِ, avant de réciter'), ('basmala', 'au début de chaque sourate, sauf At-Tawba')])

L4 = lesson(e=E, n=4, title='Les erreurs à éviter : erreur claire et erreur cachée', ar='لَحْنٌ',
    obj=['distinguer l’**erreur claire** et l’**erreur cachée** ;', 'repérer les confusions de lettres les plus fréquentes ;', 'corriger les erreurs de voyelles, de chadda, de soukoun et d’allongement.'],
    dec=[('g', ['', 'Erreur claire (jaliyy)', 'Erreur cachée (khafiyy)'], [['Ce que c’est', 'touche le mot : lettre, voyelle, chadda', 'touche la justesse : ghounna, madd, épaisseur'], ['Gravité', 'peut changer le sens : à éviter absolument', 'abîme la récitation : à corriger']], [1900, 4123, 4123]),
         ('t', 'Dans ' + W(1, 7, 3) + ', la fatḥa du tâ’ veut dire « **Tu** as comblé » ; une ḍamma changerait le sens. ' + W(2, 29, 19) + ' (« Omniscient ») commence par un ‘ayn ; avec une hamza, il ressemblerait à ' + W(2, 10, 9) + ' (« douloureux »).'),
         ('g', ['Lettres', 'Exemples'], [[('AR', 'ح / ه'), ('AR', W(1, 3, 1) + '  ' + W(112, 1, 2))], [('AR', 'ع / ء'), ('AR', W(2, 29, 19) + '  ' + W(112, 1, 4))], [('AR', 'ق / ك'), ('AR', W(112, 1, 1) + '  ' + W(112, 4, 4))],
                                         [('AR', 'ص / س'), ('AR', W(1, 6, 2) + '  ' + W(114, 1, 4))], [('AR', 'ض / د'), ('AR', W(1, 7, 9) + '  ' + W(1, 4, 3))]], [3000, 7146])],
    ecoute=['Posez la main sur la gorge : le ḥâ’ frotte au milieu de la gorge, le hâ’ est un souffle léger.'],
    ret=['L’**erreur claire** touche le mot : elle peut changer le sens.', 'L’**erreur cachée** touche la justesse.', 'Paires à ne pas confondre : ḥâ’/hâ’, ‘ayn/hamza, qâf/kâf, ṣâd/sîn, ṭâ’/tâ’, ḍâd/dâl, dhâl/zây, thâ’/sîn.'],
    lis=[[W(1, 3, 1), W(112, 1, 2), W(113, 5, 3), W(112, 4, 3)], [W(2, 29, 19), W(2, 10, 9), W(1, 2, 4), W(112, 1, 4)], [W(112, 1, 1), W(112, 4, 4), W(113, 1, 4), W(102, 4, 2)],
         [W(1, 6, 2), W(114, 1, 4), W(103, 3, 5), W(112, 2, 2)], [W(1, 7, 9), W(1, 4, 3), W(1, 7, 6), W(1, 4, 2)], [W(1, 7, 2), W(99, 1, 2), W(102, 4, 1), W(102, 4, 3)]],
    lis_corr=['Dans chaque ligne, faites entendre la différence entre les deux premiers mots.'],
    mots=[M(1, 7, 3, note='« Tu as comblé »'), M(2, 29, 19, note='‘ayn'), M(2, 10, 9, note='hamza'), M(112, 1, 1, note='qâf'), M(1, 5, 1, note='chadda'), M(1, 4, 1, note='allongement')],
    cahier=[dict(title='Claire ou cachée ?', instr='Écrivez C (claire) ou K (cachée).', kind='bul', data=['Lire un kâf à la place d’un qâf. ……', 'Raccourcir l’alif de ٱلضَّآلِّينَ. ……', 'Oublier la chadda de إِيَّاكَ. ……', 'Rendre épais le râ’ de ٱلرَّحِيمِ. ……'],
                 corr=['1. C • 2. K • 3. C • 4. K.']),
            dict(title='Je classe les lettres', instr='Classez : épaisses ou fines ?', kind='classer', data=(['ص', 'س', 'ض', 'د', 'ط', 'ت', 'ق', 'ك'], ['Épaisse', 'Fine']), corr=['Épaisses : ص ض ط ق • Fines : س د ت ك.'])],
    mini=[('Une erreur qui change une lettre ou une voyelle est…', ['une erreur claire', 'une erreur cachée', 'une sakta']), ('Oublier une ghounna est…', ['une erreur cachée', 'une erreur claire', 'permis']),
          ('Dans أَنْعَمْتَ, une ḍamma sur le tâ’ donnerait…', ['« j’ai comblé » : le sens change', 'le même sens', 'une erreur cachée'])],
    cards=[('laḥn jaliyy', 'erreur claire : touche le mot, peut changer le sens'), ('laḥn khafiyy', 'erreur cachée : touche la justesse')])

ETAPE = dict(n=1, title='Bien commencer ma récitation', ar='ٱلتَّجْوِيدُ', aim='Savoir ce qu’est le tajwîd, choisir son rythme, bien commencer et éviter les erreurs.',
    intro=[], lessons=[L1, L2, L3, L4],
    bilan=['Je sais ce qu’est le tajwîd.', 'Je connais les trois rythmes.', 'Je dis l’isti‘âdha et la basmala correctement.', 'Je distingue erreur claire et erreur cachée.'],
    vigilance=['Faire écouter avant de faire lire : le tajwîd passe d’abord par l’oreille.', 'Repérer dès le départ les confusions de lettres (ح/ه, ع/ء, ق/ك…) et les noter dans le carnet de chaque élève.', 'Exiger le rythme taḥqîq pendant l’apprentissage.'],
    jeu_conseille='L’écho (leçon 1) et feu vert, feu rouge (leçon 3).', duree='4 leçons + 1 séance de révision et de bilan',
    defi='Commencer par l’isti‘âdha et la basmala, puis réciter toute la Fâtiḥa au rythme tadwîr, sans erreur claire.')
